/**
 * Creates the bid desk / library tables (src/db/schema/bids.ts) in a database that already
 * has the committed migrations applied — WITHOUT generating a migration file.
 *
 * Why this exists: the migration for these tables is generated by the lead at integration
 * (`pnpm db:generate`). Until then, local development and the bids/library tests need the
 * tables, so this script diffs "foundation schema" against "foundation + bids schema" with
 * drizzle-kit's API and runs the resulting CREATE statements. Once a real migration creates
 * the tables it becomes a no-op.
 *
 *   pnpm tsx scripts/bids/apply-schema.ts            # create if missing (DATABASE_URL)
 *   pnpm tsx scripts/bids/apply-schema.ts --reset    # drop + recreate (local only)
 */
import postgres from "postgres";
import * as appSchema from "../../src/db/schema/app";
import * as authSchema from "../../src/db/schema/auth";
import * as bidsSchema from "../../src/db/schema/bids";

export const BIDS_TABLES = ["bid_credits", "company_facts", "library_docs", "bid_questions", "bid_requirements", "bid_files", "bids"] as const;

export async function bidsSchemaStatements(): Promise<string[]> {
  // Loaded on demand and cleaned up after: drizzle-kit/api adds enumerable properties to
  // Array.prototype (`random`), which makes pdf.js refuse to load in the same process.
  const { generateDrizzleJson, generateMigration } = await import("drizzle-kit/api");
  try {
    const foundation = generateDrizzleJson({ ...authSchema, ...appSchema });
    const withBids = generateDrizzleJson({ ...authSchema, ...appSchema, ...bidsSchema }, foundation.id);
    return await generateMigration(foundation, withBids);
  } finally {
    for (const key in []) delete (Array.prototype as unknown as Record<string, unknown>)[key];
  }
}

/** Creates the tables when `bids` does not exist yet. Returns true when it created them. */
export async function applyBidsSchema(databaseUrl: string, options: { reset?: boolean } = {}): Promise<boolean> {
  const client = postgres(databaseUrl, { prepare: false, max: 1, onnotice: () => {} });
  try {
    if (options.reset) {
      const host = new URL(databaseUrl).hostname;
      if (!["localhost", "127.0.0.1"].includes(host)) throw new Error(`Refusing to reset bids tables on ${host}`);
      await client.unsafe(BIDS_TABLES.map((table) => `drop table if exists "${table}" cascade;`).join("\n"));
    }
    const [existing] = await client`select to_regclass('public.bids') as name`;
    if (existing?.name) return false;
    const statements = await bidsSchemaStatements();
    await client.begin(async (tx) => {
      for (const statement of statements) await tx.unsafe(statement);
    });
    return true;
  } finally {
    await client.end({ timeout: 5 });
  }
}

const invokedDirectly = process.argv[1]?.replace(/\\/g, "/").endsWith("scripts/bids/apply-schema.ts");
if (invokedDirectly) {
  for (const file of [".env.local", ".env"]) {
    try {
      process.loadEnvFile(file);
    } catch {
      // optional
    }
  }
  const url = process.env.DATABASE_URL;
  if (!url) {
    console.error("[bids:schema] DATABASE_URL is not set");
    process.exit(1);
  }
  applyBidsSchema(url, { reset: process.argv.includes("--reset") })
    .then((created) => {
      console.log(created ? "[bids:schema] tables created" : "[bids:schema] tables already exist (use --reset to recreate locally)");
    })
    .catch((error: unknown) => {
      console.error("[bids:schema] failed:", error instanceof Error ? error.message : error);
      process.exit(1);
    });
}
